0x01.1.2 漏洞解读¶
路径：PbootCMS-V1.2.1\apps\home\controller\MessageController.php 方法：add(
// 留言新增 public function add() { if ($_POST) { if (time() - session(&#x27;lastsub&#x27;) &lt; 10) { alert_back(&#x27;您提交太频繁了，请稍后再试！&#x27;); } // 验证码验证 $checkcode = post(&#x27;checkcode&#x27;); if ($this-&gt;config(&#x27;message_check_code&#x27;)) { // if (! $checkcode) { // alert_back(&#x27;验证码不能为空！&#x27;); // } if ($checkcode != session(&#x27;checkcode&#x27;)) { alert_back(&#x27;验证码错误！&#x27;); } } // 读取字段 if (! $form = $this-&gt;model-&gt;getFormField(1)) { alert_back(&#x27;留言表单不存在任何字段，请核对后重试！&#x27;); } // 接收数据 $mail_body = &#x27;&#x27;; foreach ($form as $value) { $field_data = post($value-&gt;name); if (is_array($field_data)) { // 如果是多选等情况时转换 $field_data = implode(&#x27;,&#x27;, $field_data); } if ($value-&gt;required &amp;&amp; ! $field_data) { alert_back($value-&gt;description . &#x27;不能为空！&#x27;); } else { $data[$value-&gt;name] = post($value-&gt;name); $mail_body .= $value-&gt;description . &#x27;：&#x27; . post($value-&gt;name) . &#x27;&lt;br&gt;&#x27;; } } // 设置额外数据 if ($data) { $data[&#x27;acode&#x27;] = session(&#x27;lg&#x27;); $data[&#x27;user_ip&#x27;] = ip2long(get_user_ip()); $data[&#x27;user_os&#x27;] = get_user_os(); $data[&#x27;user_bs&#x27;] = get_user_bs(); $data[&#x27;recontent&#x27;] = &#x27;&#x27;; $data[&#x27;status&#x27;] = 0; $data[&#x27;create_user&#x27;] = &#x27;guest&#x27;; $data[&#x27;update_user&#x27;] = &#x27;guest&#x27;; } if ($this-&gt;model-&gt;addMessage($data)) { session(&#x27;lastsub&#x27;, time()); // 记录最后提交时间 $this-&gt;log(&#x27;留言提交成功！&#x27;); if ($this-&gt;config(&#x27;message_send_mail&#x27;) &amp;&amp; $this-&gt;config(&#x27;message_send_to&#x27;)) { $mail_subject = &quot;【PbootCMS】您有新的表单数据，请注意查收！&quot;; $mail_body .= &#x27;&lt;br&gt;来自网站&#x27; . get_http_url() . &#x27;（&#x27; . date(&#x27;Y-m-d H:i:s&#x27;) . &#x27;）&#x27;; sendmail($this-&gt;config(), $this-&gt;config(&#x27;message_send_to&#x27;), $mail_subject, $mail_body); } alert_location(&#x27;提交成功！&#x27;, &#x27;-1&#x27;); } else { $this-&gt;log(&#x27;留言提交失败！&#x27;); alert_back(&#x27;提交失败！&#x27;); } } else { error(&#x27;提交失败，请使用POST方式提交！&#x27;); } }
可以看到，整个逻辑下来的意思就是说，查询出数据库一条数据，然后接收外部 POST 内容，只匹配数据库的字段，相同才会拼接到 $_data数组
然后就会带入 $this-&gt;model-&gt;addMessage(data) 执行语句
